{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01CMMiuTm9QSbJB5zo5ChqjX","type":"tool_result","content":"1	import { type Actions, createGlobalStore, useStoreWithActions, type Visit } from '@openmrs/esm-framework';
2	
3	export interface PatientChartStore {
4	  patientUuid: string;
5	  patient: fhir.Patient;
6	  visitContext: Visit;
7	  mutateVisitContext: () => void;
8	  /**
9	   * The uuid of the visit context the patient-chart workspace group was last launched with.
10	   * Note that when the visit context is changed, the workspaces group (with stale visit context)
11	   * must close and reopen, and during that process its visitContext might differ from 
12	   * `store.visitContext`
13	   */
14	  workspaceGroupVisitUuid?: string | null;
15	}
16	
17	const patientChartStoreName = 'patient-chart-global-store';
18	
19	const patientChartStore = createGlobalStore<PatientChartStore>(patientChartStoreName, {
20	  patientUuid: null,
21	  patient: null,
22	  visitContext: null,
23	  mutateVisitContext: null,
24	  workspaceGroupVisitUuid: null,
25	});
26	
27	const patientChartStoreActions = {
28	  setPatient(_, patient: fhir.Patient) {
29	    return { patient, patientUuid: patient?.id ?? null };
30	  },
31	  setVisitContext(_, visitContext: Visit, mutateVisitContext: () => void) {
32	    return { visitContext, mutateVisitContext };
33	  },
34	} satisfies Actions<PatientChartStore>;
35	
36	/**
37	 * Records the visit context the patient-chart workspace group was last launched with.
38	 * Only the patient chart should call this, after it launches its workspace group.
39	 */
40	export function setPatientChartWorkspaceGroupVisitUuid(workspaceGroupVisitUuid: string | null) {
41	  patientChartStore.setState({ workspaceGroupVisitUuid });
42	}
43	
44	/**
45	 * Hook to access the values and sets of the patient chart store.
46	 * Note: This hooks SHOULD only be used by components inside the patient chart app.
47	 *
48	 * Workspaces / extensions that can be mounted by other apps (ex: the start visit form in the queue's app,
49	 * the clinical forms workspace in the ward app)
50	 * should have the patient / visitContext explicitly passed in as props.
51	 *
52	 * As a safety feature, this hook requires the patientUuid as the input, and only
53	 * returns the actual store values if input patientUuid matches that in the store.
54	 */
55	export function usePatientChartStore(patientUuid: string) {
56	  const store = useStoreWithActions(patientChartStore, patientChartStoreActions);
57	  if (store.patientUuid === patientUuid) {
58	    return store;
59	  } else {
60	    const fakeStore: typeof store = {
61	      ...store,
62	      mutateVisitContext: null,
63	      setVisitContext: () => {},
64	      patient: null,
65	      patientUuid: null,
66	      visitContext: null,
67	      workspaceGroupVisitUuid: null,
68	    };
69	    return fakeStore;
